input.content:
"use server";

import { revalidatePath } from "next/cache";

// In-memory store for demo purposes
let notificationEnabled = false;

export async function toggleNotifications() {
  // Toggle the notification preference
  notificationEnabled = !notificationEnabled;

  // Revalidate the current page to reflect the updated preference
  revalidatePath("/");

  return { enabled: notificationEnabled };
}

export async function getNotificationPreference() {
  return { enabled: notificationEnabled };
}

import { toggleNotifications, getNotificationPreference } from "./actions/notifications";

export default async function Home() {
  const { enabled } = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <button type="submit">
          Notifications: {enabled ? "ON" : "OFF"}
        </button>
      </form>
    </main>
  );
}

